INSERT INTO `elections` (`id`, `title`, `organization_name`, `period_label`, `description`, `start_time`, `end_time`, `status`, `is_result_published`, `created_at`, `updated_at`) VALUES
(1, 'Pemilihan Ketua Badan Eksekutif Mahasiswa (BEM)', 'BEM Universitas', '2026/2027', 'Pemilihan Raya Ketua BEM Universitas Periode 2026/2027 secara langsung, umum, bebas, dan rahasia (Secret Ballot) bagi seluruh mahasiswa aktif.', DATE_SUB(NOW(), INTERVAL 1 DAY), DATE_ADD(NOW(), INTERVAL 7 DAY), 'active', 0, NOW(), NOW());
INSERT INTO `candidates` (`election_id`, `candidate_number`, `name`, `nim`, `jenjang`, `program_studi`, `tagline`, `photo_path`, `vision`, `mission`, `created_at`, `updated_at`) VALUES
(1, 1, 'Dimas Arya Pratama', '220101011', 'S1', 'Teknik Informatika', 'Kampus Kolaboratif, Inovatif, dan Berdampak Nyata', NULL, 'Mewujudkan BEM Universitas sebagai poros pergerakan mahasiswa yang inklusif, berbasis inovasi digital, dan responsif terhadap advokasi kesejahteraan mahasiswa.', '1. Membangun sistem advokasi terpadu yang transparan dan cepat tanggap bagi seluruh mahasiswa.\n2. Mengakselerasi digitalisasi layanan organisasi dan inkubasi karya prestasi mahasiswa lintas program studi.\n3. Memperluas jejaring kolaborasi strategis dengan mitra industri, alumni, dan masyarakat.', NOW(), NOW()),
(1, 2, 'Aulia Rahma Wijaya', '220102024', 'S1', 'Manajemen', 'Sinergi Karya untuk Kemajuan Bersama', NULL, 'Menjadikan organisasi kemahasiswaan sebagai ruang tumbuh yang progresif, berintegritas tinggi, dan berorientasi pada pengembangan kepemimpinan masa depan.', '1. Menghadirkan program pengembangan soft-skill, kepemimpinan, dan kewirausahaan mahasiswa secara berkelanjutan.\n2. Menguatkan sinergi antar Himpunan Mahasiswa Jurusan (HMJ) dan Unit Kegiatan Mahasiswa (UKM).\n3. Menyelenggarakan tata kelola anggaran dan program kerja organisasi yang akuntabel serta terbuka.', NOW(), NOW()),
(1, 3, 'Bagas Adi Nugraha', '220103018', 'S1', 'Sistem Informasi', 'Bergerak Bersama, Wujudkan Kampus Berdaya', NULL, 'Menciptakan ekosistem kemahasiswaan yang aspiratif, solutif, dan unggul dalam riset serta pengabdian masyarakat.', '1. Mengoptimalkan forum aspirasi mahasiswa secara berkala bersama pimpinan kampus.\n2. Mendorong lahirnya komunitas riset, kompetisi nasional, dan pengabdian desa binaan.\n3. Menciptakan lingkungan kampus yang aman, ramah, dan inklusif bagi seluruh sivitas akademika.', NOW(), NOW());
